function card(plan,kind){const audience=kind==='bundle'?bundleAudience[plan.id]:memberAudience[plan.id],featured=plan.featured||plan.id==='advanced';return `<article class="purchase-plan commerce-center-plan commerce-center-plan-${kind} commerce-center-plan-${plan.id} ${featured?'featured':''} ${plan.available?'commerce-center-plan-free':''}"><div class="commerce-center-plan-cover"><div class="commerce-center-plan-decoration" aria-hidden="true">${icon(kind==='bundle'?'grid':'diamond',88)}</div><div class="purchase-plan-top"><span class="purchase-plan-icon">${icon(plan.available?'user':kind==='bundle'?'grid':'diamond',24)}</span><span class="purchase-status">${plan.available?'当前可用':kind==='bundle'?'组合方案':'规划会员'}</span></div><h3>${plan.name}</h3><p class="commerce-center-audience">${audience}</p><div class="purchase-price"><b>${plan.available?'免费':'<small>¥</small>'+plan.price}</b><span>${plan.available?'本地功能体验':kind==='bundle'?'参考价 / 套':'参考价 · 计价单位待确认'}</span></div></div><div class="commerce-center-plan-body"><div class="commerce-center-feature-label">${plan.available?'从这些功能开始':kind==='bundle'?'一套包含这些服务':'了解规划权益'}<span>${plan.features.length} 项</span></div><ul>${plan.features.map(f=>`<li><span aria-hidden="true">${icon('check',14)}</span>${f.replace(/^规划：/,'')}</li>`).join('')}</ul>${plan.available?'<a class="btn secondary full" href="#home">继续免费体验</a>':`<a class="btn ${featured?'primary':'secondary'} full" href="#membership/checkout?kind=${kind}&plan=${plan.id}&quantity=1">${kind==='bundle'?'查看套餐详情':'查看会员权益'} ${icon('arrow',16)}</a>`}<small class="commerce-center-plan-footnote">${plan.available?'随时保存你的研究内容':'尚未上架 · 确认规则后开放购买'}</small></div></article>`;}
function publishedMemberCard(product,index){const price=(product.priceCents/100).toFixed(2).replace(/\.00$/,''),title=escapeHTML(product.title),description=escapeHTML(product.description),tone=['standard','advanced','pro'][index%3];return `<article class="purchase-plan commerce-center-plan commerce-center-plan-member commerce-center-plan-live commerce-center-plan-${tone}" data-member-product="${escapeHTML(product.id)}"><div class="commerce-center-plan-cover"><div class="commerce-center-plan-decoration" aria-hidden="true">${icon('diamond',88)}</div><div class="purchase-plan-top"><span class="purchase-plan-icon">${icon('diamond',24)}</span><span class="purchase-status">已上架</span></div><h3>${title}</h3><p class="commerce-center-audience">会员有效期 ${product.durationDays} 天</p><div class="purchase-price"><b><small>¥</small>${price}</b><span>人民币 / ${product.durationDays} 天</span></div></div><div class="commerce-center-plan-body"><div class="commerce-center-feature-label">商品说明<span>${product.durationDays} 天</span></div><p class="commerce-member-description">${description}</p><a class="btn primary full" href="#membership/pay?product=${encodeURIComponent(product.id)}">确认购买 ${icon('arrow',16)}</a><small class="commerce-center-plan-footnote">以收银台确认的金额与说明为准</small></div></article>`;}
function validOffer(product,type,products){const days=product?.entitlement?.durationDays??product?.durationDays;if(!product||typeof product.id!=='string'||!product.id||product.id.length>180||products.filter(p=>p?.id===product.id).length!==1||product.status!=='active'||product.currency!=='CNY'||(product?.entitlement?.type||product?.entitlementType)!==type||!Number.isSafeInteger(product.priceCents)||product.priceCents<1||product.priceCents>10000000||!Number.isSafeInteger(days)||days<1||days>366||typeof product.title!=='string'||!product.title.trim()||product.title.length>80||typeof product.description!=='string'||!product.description.trim()||product.description.length>1000)return null;
 const items=product.bundleItems??product.entitlement?.bundleItems;
 if(type==='bundle'&&(!Array.isArray(items)||!items.length||items.length>20||items.some(item=>!item||typeof item.key!=='string'||!/^[a-z][a-z0-9-]{0,63}$/.test(item.key)||items.filter(other=>other?.key===item.key).length!==1||typeof item.title!=='string'||!item.title.trim()||item.title.length>80||!Number.isSafeInteger(item.quantity)||item.quantity<1||item.quantity>100000)))return null;
 return {...product,durationDays:days,...(type==='bundle'?{bundleItems:items}:{})};
}
function watchOfferCatalogue(section,onOptions,onUnavailable,{ignoreQuantity=false}={}){
 const ownerWindow=window,ownerDocument=document,mountHash=location.hash,controller=new AbortController();let disposed=false,timedOut=false;
 const routeKey=hash=>{if(!ignoreQuantity)return hash;const [route,query]=hash.split('?');const params=new URLSearchParams(query||'');params.delete('quantity');params.sort();return route+'?'+params.toString();};
 const sameRoute=()=>routeKey(ownerWindow.location.hash)===routeKey(mountHash);
 const alive=()=>!disposed&&!timedOut&&section.isConnected&&sameRoute()&&document===ownerDocument;
 const failed=()=>{if(alive())onUnavailable();};
 const timeout=ownerWindow.setTimeout(()=>{failed();timedOut=true;controller.abort();},12000);
 const dispose=()=>{if(disposed)return;disposed=true;ownerWindow.clearTimeout(timeout);controller.abort();ownerWindow.removeEventListener('hashchange',onRouteChange);if(disposeCreditPage===dispose)disposeCreditPage=null;};
 const onRouteChange=()=>{if(!sameRoute())dispose();};disposeCreditPage=dispose;ownerWindow.addEventListener('hashchange',onRouteChange);
 const fetchOptions=typeof ownerWindow.fetch==='function'?ownerWindow.fetch.bind(ownerWindow):globalThis.fetch;
 Promise.resolve().then(()=>alive()?fetchOptions('/api/payments/options',{method:'GET',credentials:'same-origin',cache:'no-store',headers:{accept:'application/json'},signal:controller.signal}):null).then(async response=>{if(!alive()||!response)return;if(!response.ok)throw new Error('payment options unavailable');const options=await response.json();if(!alive())return;if(!options||!Array.isArray(options.products)||!Array.isArray(options.channels))throw new Error('invalid payment options');onOptions(options);}).catch(error=>{if(!alive()||error?.name==='AbortError'&&!timedOut)return;failed();}).finally(()=>ownerWindow.clearTimeout(timeout));return {dispose};
}
function publishedBundleCard(product,plan){const price=(product.priceCents/100).toFixed(2).replace(/\.00$/,''),featured=plan.featured,tone=plan.id;return `<article class="purchase-plan commerce-center-plan commerce-center-plan-bundle commerce-center-plan-live commerce-center-plan-${tone} ${featured?'featured':''}" data-bundle-product="${escapeHTML(product.id)}"><div class="commerce-center-plan-cover"><div class="commerce-center-plan-decoration" aria-hidden="true">${icon('grid',88)}</div><div class="purchase-plan-top"><span class="purchase-plan-icon">${icon('grid',24)}</span><span class="purchase-status">已上架</span></div><h3>${escapeHTML(product.title)}</h3><p class="commerce-center-audience">套餐有效期 ${product.durationDays} 天</p><div class="purchase-price"><b><small>¥</small>${price}</b><span>人民币 / 套</span></div></div><div class="commerce-center-plan-body"><div class="commerce-center-feature-label">一套包含这些服务<span>${product.bundleItems.length} 项</span></div><ul>${product.bundleItems.map(item=>`<li><span aria-hidden="true">${icon('check',14)}</span>${escapeHTML(item.title)} × ${item.quantity}</li>`).join('')}</ul><p class="commerce-member-description">${escapeHTML(product.description)}</p><a class="btn ${featured?'primary':'secondary'} full" href="#membership/pay?product=${encodeURIComponent(product.id)}">确认购买 ${icon('arrow',16)}</a><small class="commerce-center-plan-footnote">付款后记录本次套餐服务项与有效期</small></div></article>`;}
function loadPublishedBundles(dashboard,plans){const section=dashboard.querySelector('[data-bundle-offers]'),status=section.querySelector('[data-bundle-status]');return watchOfferCatalogue(section,options=>{
 const products=options.products.map(product=>validOffer(product,'bundle',options.products)).filter(Boolean);
 let available=0;section.querySelector('[data-bundle-plan-grid]').innerHTML=plans.map((plan,index)=>{const product=products.find(p=>p.id==='bundle-'+plan.id);if(!product)return card(plan,'bundle');available++;return publishedBundleCard(product,plan);}).join('');
 status.textContent=available?'已核对已上架套餐 · 确认商品后进入收银台':'套餐尚未上架 · 请等待正式发布';
 section.querySelector('[data-bundle-fineprint]').textContent=available?'已上架套餐的价格、服务项与有效期以后台发布及付款确认页为准；未上架方案仅供比较。':'未上架套餐仅供比较，需在后台确认有效期及可交付服务后上架。';
 },()=>{status.textContent='套餐商品信息暂未取得 · 当前仅展示参考方案';});}
function purchaseWays(){return `<section class="commerce-center-methods" aria-labelledby="commerce-ways-heading"><div class="commerce-center-section-title"><h2 id="commerce-ways-heading">三种方式，按你的研究节奏选择</h2><p>会员、积分与套餐分别满足持续、零散和集中使用的需要。</p></div><div class="commerce-center-method-grid">${commerceOptions.map(o=>`<article><span>${icon(o.icon,20)}</span><div><h3>${o.title}</h3><p>${o.caption}</p><small>${o.scene}</small></div></article>`).join('')}</div></section>`;}
function purchaseFAQ(){return `<section class="card purchase-faq commerce-center-faq"><h2>购买前，了解这些就够了</h2><details><summary>会员、科研积分和套餐有什么区别？</summary><p>会员面向持续使用，按周期提供组合权益；科研积分按档位购买，具体价格、到账数量以服务器当前发布的商品及付款确认页为准；套餐把特定阶段的服务按次数组合。标注“方案预览”的内容尚未上架；正式商品的周期和服务范围以当前商品说明为准。</p></details><details><summary>确认购买后如何付款？</summary><p>确认购买后，在收银台选择当前可用的支付方式。暂未开放收款时不会生成付款二维码。当前在线积分消耗未开放，充值只增加账户余额，不会开通尚未开放的 AI 服务。请确认需求后再购买。</p></details><details><summary>会员会自动续费吗？购买能保证检测结果吗？</summary><p>当前不启用会员自动续费。工具用于辅助研究与内容整理，不承诺检测分数或论文通过。实际服务范围、有效期、退款与开票规则以购买时公布的内容为准。</p></details></section>`;}
