 const form=$('.commerce-credit-form'),ownerWindow=window,ownerDocument=document,mountHash=location.hash,controller=new AbortController();let disposed=false,timedOut=false;const readTimeout=ownerWindow.setTimeout(()=>{timedOut=true;controller.abort();},12000);
