 $('#purchase-quantity').oninput=()=>{const n=Number($('#purchase-quantity').value);if(!Number.isInteger(n)||n<1||n>365){$('#quantity-error').textContent='请输入 1～365 的整数数量。';$('#reference-total').textContent='—';$('#selected-quantity').textContent='待修正';return;}window.history.replaceState(null,'',`#membership/checkout?kind=${s.kind}&plan=${p.id}&quantity=${n}`);$('#quantity-error').textContent='';$('#reference-total').textContent='¥'+n*p.price;$('#selected-quantity').textContent=String(n);};
