  checkoutSection.querySelector('.purchase-confirm').innerHTML=`<span class="purchase-confirm-label">订单确认</span><h2>${escapeHTML(product.title)}</h2><dl><div><dt>购买数量</dt><dd>1 份</dd></div><div><dt>有效期</dt><dd>${product.durationDays} 天</dd></div><div><dt>应付金额</dt><dd>¥${amount}</dd></div></dl><div class="purchase-payment-state">${icon('shield',20)}<div><b>在收银台选择支付方式</b><p>收银台将再次核对商品及所选渠道。当前页面不会自动创建订单。</p></div></div><a class="btn primary full" href="#membership/pay?product=${encodeURIComponent(product.id)}">确认购买 ${icon('arrow',16)}</a><p class="purchase-confirm-note">${escapeHTML(product.description)}</p>`;
